Scripts.screen.ps1:
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
Set-Location $repo
$runner = Join-Path (Split-Path $repo -Parent) 'OfficeIMO-excel-csv-throughput/Ignore/Benchmarks/excel-csv-broad/compare/bin/Release/net10.0/Compare.dll'
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = $PSScriptRoot
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'screen-cases.json'
$env:OFFICEIMO_COMPARISON_MASK = '65535'
$env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
$env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
function Assert-Frozen {
    git diff --no-ext-diff --no-textconv --no-color --full-index --binary --output=Ignore/Benchmarks/csv-direct-text/running.patch -- OfficeIMO.CSV OfficeIMO.CSV.Tests
    if ($LASTEXITCODE -or (Get-FileHash (Join-Path $PSScriptRoot 'running.patch')).Hash -ne '90A5112A83AC7FBC0CA115E7DE8DE187F4F79CFE564BF5318515C493BE7C4E75') { throw 'CSV candidate source changed' }
    $manifest=Get-Content (Join-Path $PSScriptRoot 'binary-manifest.json') -Raw | ConvertFrom-Json
    foreach($item in $manifest) { foreach($side in 'baseline','candidate') {
        if((Get-FileHash (Join-Path $PSScriptRoot "$side-csv/$($item.File)")).Hash -ne $item.$side) { throw "CSV binary changed: $side/$($item.File)" }
    } }
}
Assert-Frozen
dotnet $runner --validate *> (Join-Path $PSScriptRoot 'validation.log')
if($LASTEXITCODE) { throw 'CSV output validation failed' }
Write-Output 'Validated 12 CSV direct-buffer workloads.'
$output=Join-Path $PSScriptRoot 'screen-native'
if(Test-Path $output) { throw 'Output exists' }
Push-Location (Resolve-Path (Join-Path (Split-Path $runner) '../../..'))
try {
    dotnet $runner --filter '*SnapshotComparison*' --warmupCount 24 --iterationCount 12 --invocationCount 4 --unrollFactor 1 --outliers DontRemove --artifacts $output *> (Join-Path $PSScriptRoot 'screen-native.log')
    if($LASTEXITCODE) { throw 'CSV native screen failed' }
} finally { Pop-Location }
$report=Get-Content (Join-Path $output 'results/SnapshotComparison-report-full.json') -Raw | ConvertFrom-Json
if($report.Benchmarks.Count -ne 24 -or @($report.Benchmarks | Where-Object {$_.Statistics.N -ne 12}).Count) { throw 'Incomplete CSV screen' }
Assert-Frozen
Write-Output 'Completed all 24 native CSV direct-buffer screen cases.'

